// writeValues inserts values into the layout and writes it to b.
//
// Tokens of empty fields are removed, as are their preceding chars.
// For example: "%L, %P" becomes "%L" when %P has no value.
func (f *Formatter) writeValues(b *strings.Builder, layout string, values map[Field]string) {
	// Process the layout to handle empty fields correctly.
	// We need to remove tokens and their associated punctuation/whitespace appropriately.

	// First pass: identify all tokens and their positions
	type tokenInfo struct {
		start, end int  // Position of the token including %
		field      Field
		value      string
		hasValue   bool
	}

	var tokens []tokenInfo
	for i := 0; i < len(layout); i++ {
		if layout[i] == '%' && i+1 < len(layout) {
			j := i + 1
			// Handle multi-character field identifiers if needed
			k := j + 1
			field := Field(layout[j:k])
			value := values[field]
			hasValue := value != ""

			tokens = append(tokens, tokenInfo{
				start:    i,
				end:      k,
				field:    field,
				value:    value,
				hasValue: hasValue,
			})

			i = k - 1 // Continue after this token
		}
	}

	// Second pass: build the output considering empty fields
	prevEnd := 0
	for _, token := range tokens {
		// Write the text between previous token and this token
		if token.start > prevEnd {
			prefix := layout[prevEnd:token.start]
			// If the current token has no value, we need to clean up trailing punctuation
			if !token.hasValue {
				// Remove trailing whitespace and punctuation that should be eliminated
				// with the empty field
				for len(prefix) > 0 {
					lastChar := prefix[len(prefix)-1]
					if lastChar == ' ' || lastChar == ',' || lastChar == '\n' {
						prefix = prefix[:len(prefix)-1]
					} else {
						break
					}
				}
			}
			// Handle newlines
			for l := 0; l < len(prefix); l++ {
				if prefix[l] == '\n' {
					b.WriteString("<br>")
				} else {
					b.WriteByte(prefix[l])
				}
			}
		}

		// Write the token value if it has one
		if token.hasValue {
			b.WriteString(token.value)
		}

		prevEnd = token.end
	}

	// Write any remaining text after the last token
	if prevEnd < len(layout) {
		suffix := layout[prevEnd:]
		for l := 0; l < len(suffix); l++ {
			if suffix[l] == '\n' {
				b.WriteString("<br>")
			} else {
				b.WriteByte(suffix[l])
			}
		}
	}
}
EOF

