+
+// getClass returns the HTML class for the given field.
+func (f *Formatter) getClass(field Field) string {
+	var class string
+	switch field {
+	case FieldLine1:
+		class = "line1"
+	case FieldLine2:
+		class = "line2"
+	case FieldLine3:
+		class = "line3"
+	case FieldSublocality:
+		class = "sublocality"
+	case FieldLocality:
+		class = "locality"
+	case FieldRegion:
+		class = "region"
+	case FieldPostalCode:
+		class = "postal-code"
+	}
+
+	return class
+}
+
+// getValues returns all values for the given address, keyed by field.
+//
